messages.handler:
return function (env) {
  var t = String(env.type || '').toLowerCase();
  var q = String(env.title || '').trim();
  var o = String(env.options || '').trim();
  if (!q) throw new Error('题目不能为空');
  var rule = t === 'single' ? '单选仅答一个大写字母。' :
    t === 'multiple' ? '多选仅答全部正确字母，升序连写，如ACD。' :
    t === 'judgement' ? '判断仅答对或错。' :
    '填空答JSON数组，每空一项；解答题仅用一项简明作答，计算保留必要公式和结果。';
  if (t === 'single' || t === 'multiple') {
    o = o.split(/\r?\n/).map(function (s) { return s.trim(); }).filter(Boolean).map(function (s, i) {
      return /^[A-Z][.．、:：)）\s]/i.test(s) ? s : String.fromCharCode(65 + i) + '. ' + s;
    }).join('\n');
  }
  return [
    { role: 'system', content: '准确答题。' + rule + '不确定仅答未知。' },
    { role: 'user', content: q + (o ? '\n' + o : '') }
  ];
};

handler:
return function (res) {
  if (res && res.error) throw new Error(res.error.message || '接口返回错误');
  var x = res && res.choices && res.choices[0];
  if (!x) return undefined;
  if (x.finish_reason === 'length') throw new Error('答案被截断，可将max_tokens处理器中的512调高');
  if (x.finish_reason && x.finish_reason !== 'stop') throw new Error('模型未正常完成答案：' + x.finish_reason);
  if (x.message && x.message.refusal) throw new Error('模型未返回答案');
  var c = x.message && x.message.content;
  if (typeof c !== 'string') return undefined;
  c = c.trim().replace(/^```(?:json)?\s*\n?([\s\S]*?)\n?```$/i, '$1').trim();
  if (!c || /^(未知|无法确定|不确定)[。.!！]?$/.test(c)) return undefined;
  if (c[0] === '[') {
    var a;
    try { a = JSON.parse(c); } catch (_) { throw new Error('填空或解答格式错误，请重试'); }
    if (!Array.isArray(a) || !a.length || a.some(function (v) { return typeof v !== 'string' && typeof v !== 'number'; })) throw new Error('答案数组无效');
    a = a.map(String);
    if (a.some(function (v) { return !v.trim(); })) return undefined;
    c = JSON.stringify(a);
  }
  return [undefined, c, { ai: true }];
};
